/* ═══════ COLOR PALETTE ═══════ */
const CLR={black:[0,0,0],blue:[0,85,164],green:[0,135,81],red:[206,17,38],white:[255,255,255],yellow:[255,205,0],orange:[255,136,62],light_blue:[110,187,233],maroon:[124,35,74],navy:[36,61,130],gold:[232,183,33],cyan:[0,180,216]};
const hex=n=>{const c=CLR[n];return c?`rgb(${c[0]},${c[1]},${c[2]})`:'rgb(128,128,128)';};
function genPal(n){const o=[];for(let i=0;i<n;i++){const h=(i*137.508)%360;o.push(`hsl(${Math.round(h)},${58+(i%3)*14}%,${48+(i%5)*7}%)`);}return o;}

/* ═══════ CONFIG ═══════ */
const GW=24,GH=16,TW=6,TH=4;
const MAX_A=10,H_MEM=8,ALPHA=0.5,CON_T=0.85,CON_RUNS=3,POL_T=0.25;
function mkRng(seed){let s=seed|0;return()=>{s=(s*1664525+1013904223)&0x7fffffff;return s/0x7fffffff;};}

/* ═══════ INTERNAL RENDERING (for agent scoring only — never displayed) ═══════ */
function renderGrid(flag,w=GW,h=GH){
  const g=Array.from({length:h},()=>Array(w).fill('white'));
  if(flag.bg){for(let r=0;r<h;r++)for(let c=0;c<w;c++)g[r][c]=flag.bg;}
  if(flag.s){const n=flag.s.length;
    if(flag.o==='v'){for(let i=0;i<n;i++){const a=Math.floor(i*w/n),b=Math.floor((i+1)*w/n);for(let r=0;r<h;r++)for(let c=a;c<b;c++)g[r][c]=flag.s[i];}}
    else{for(let i=0;i<n;i++){const a=Math.floor(i*h/n),b=Math.floor((i+1)*h/n);for(let r=a;r<b;r++)for(let c=0;c<w;c++)g[r][c]=flag.s[i];}}}
  if(flag.cross){const cy=flag.cc?Math.floor(h/2):Math.floor(h*0.44),cx=flag.cc?Math.floor(w/2):Math.floor(w*0.33),hw=Math.max(1,Math.round(Math.min(w,h)*0.03));
    for(let r=0;r<h;r++)for(let c=cx-hw;c<=cx+hw;c++)if(c>=0&&c<w)g[r][c]=flag.cross;
    for(let c=0;c<w;c++)for(let r=cy-hw;r<=cy+hw;r++)if(r>=0&&r<h)g[r][c]=flag.cross;}
  if(flag.diamond){const cr=(h-1)/2,cc=(w-1)/2,rh=h*0.4,rw=w*0.35;
    for(let r=0;r<h;r++)for(let c=0;c<w;c++)if(Math.abs(r-cr)/rh+Math.abs(c-cc)/rw<=1)g[r][c]=flag.diamond;}
  if(flag.circ){const isObj=typeof flag.circ==='object',color=isObj?flag.circ.color:flag.circ,rf=isObj?flag.circ.r:0.28;
    const cr=(h-1)/2,cc=(w-1)/2,rad=Math.min(h,w)*rf;
    for(let r=0;r<h;r++)for(let c=0;c<w;c++)if(Math.hypot(r-cr,c-cc)<=rad)g[r][c]=color;}
  if(flag.tri){const tip=Math.max(1,Math.round(w*0.5));
    for(let r=0;r<h;r++){const ct=h>1?Math.abs((2*r/(h-1))-1):0;const mx=Math.floor(tip*(1-ct));for(let c=0;c<=mx;c++)g[r][c]=flag.tri;}}
  if(flag.canton){const ch=Math.floor(h*0.5),cw=Math.floor(w*0.38);
    for(let r=0;r<ch;r++)for(let c=0;c<cw;c++)g[r][c]=flag.canton;}
  if(flag.cantonCross){const ch=Math.floor(h*0.5),cw=Math.floor(w*0.38),cx2=Math.floor(cw/2),cy2=Math.floor(ch/2),hw2=Math.max(1,Math.round(Math.min(cw,ch)*0.07));
    for(let r=0;r<ch;r++)for(let c=cx2-hw2;c<=cx2+hw2;c++)if(c>=0&&c<cw)g[r][c]=flag.cantonCross;
    for(let c=0;c<cw;c++)for(let r=cy2-hw2;r<=cy2+hw2;r++)if(r>=0&&r<ch)g[r][c]=flag.cantonCross;}
  if(flag.diag){const[upper,lower,band]=flag.diag;const bw=Math.max(2,Math.round(Math.min(w,h)*0.06));
    for(let r=0;r<h;r++)for(let c=0;c<w;c++){const d=(r/h+c/w-1)*Math.max(h,w)/2;if(Math.abs(d)<bw)g[r][c]=band;else g[r][c]=d<0?upper:lower;}}
  if(flag.bend){const bw=Math.max(2,Math.round(Math.min(w,h)*0.06));
    for(let r=0;r<h;r++)for(let c=0;c<w;c++){const d=Math.abs(r/h-c/w)*Math.max(h,w);if(d<bw)g[r][c]=flag.bend;}}
  return g;
}

